const body = params.trigger.body;
const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const owns = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
if (!isRecord(body)) throw new Error('Solicitud de identidad invalida');
const hasArgs = owns(body, 'args');
if (hasArgs && (!isRecord(body.args) || ['event_id', 'event_token', 'customer_name', 'customer_document'].some((key) => owns(body, key)))) throw new Error('Solicitud de identidad invalida');
const data = hasArgs ? body.args : body;
const required = (value, limit) => {
  if (typeof value !== 'string' || !value.trim() || value.length > limit || /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value)) throw new Error('Solicitud de identidad invalida');
  return value.trim();
};
const event_id = required(data.event_id, 36);
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(event_id)) throw new Error('Solicitud de identidad invalida');
const customer_name = required(data.customer_name, 240);
const customer_document = required(data.customer_document, 240);
const request_body = JSON.stringify({ event_id, customer_name, customer_document });
module.exports = { request_body };

const result = params.verificar_identidad || {};
const ok = result.ok === true;
const verificado = ok && result.verificado === true;
const hasConditions = Boolean(result.condiciones && typeof result.condiciones === 'object' && !Array.isArray(result.condiciones));
const speech = hasConditions ? result.condiciones.speech : null;
const spokenString = (value) => typeof value === 'string' && value.trim().length > 0;
const hasSpeech = Boolean(speech && typeof speech === 'object' && !Array.isArray(speech) && ['initialPayment', 'installmentAmount', 'installmentCount', 'firstDueDate'].every((key) => spokenString(speech[key])) && Array.isArray(speech.installmentAmounts) && speech.installmentAmounts.length > 0 && speech.installmentAmounts.every(spokenString));
const complete = !verificado || (hasConditions && hasSpeech);
module.exports = {
  ok: ok && complete,
  verificado: verificado && hasConditions && hasSpeech,
  condiciones: verificado && hasConditions && hasSpeech ? result.condiciones : null,
  code: ok && complete ? (result.verificado === false && result.code === 'DOCUMENT_NOT_UNDERSTOOD' ? 'DOCUMENT_NOT_UNDERSTOOD' : null) : 'IDENTITY_UNAVAILABLE'
};
